-- Kalaa Home: sample data for the SQL Path project "Sales performance review".
-- A fictional Indian online home-decor retailer. Two years of orders (2023 and 2024), synthetic data.
-- Generated by a fixed-seed script, so every learner sees exactly the same rows.
-- Amounts are in Indian rupees (whole rupees). Dates are ISO text (YYYY-MM-DD).
-- Deliberate data-quality issues: some city names are misspelt, use an old name or have extra spaces;
-- a few orders have no channel (NULL); cancelled and returned orders are kept in the orders table.

CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  city        TEXT NOT NULL,
  region      TEXT NOT NULL,
  signup_date TEXT NOT NULL
);


CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  name       TEXT    NOT NULL,
  category   TEXT    NOT NULL,
  unit_cost  INTEGER NOT NULL,
  list_price INTEGER NOT NULL
);


-- status is 'delivered', 'cancelled' or 'returned'. channel is 'web', 'app' or 'marketplace' (NULL when unknown).
CREATE TABLE orders (
  order_id    INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers (customer_id),
  order_date  TEXT    NOT NULL,
  channel     TEXT,
  status      TEXT    NOT NULL
);


-- One row per product in an order. unit_price is the price charged per unit; discount is the
-- rupee discount on the whole line. Line revenue = quantity * unit_price - discount.
CREATE TABLE order_items (
  order_id   INTEGER NOT NULL REFERENCES orders (order_id),
  product_id INTEGER NOT NULL REFERENCES products (product_id),
  quantity   INTEGER NOT NULL,
  unit_price INTEGER NOT NULL,
  discount   INTEGER NOT NULL,
  PRIMARY KEY (order_id, product_id)
);


-- Quarterly net revenue targets for 2024, per region.
CREATE TABLE targets (
  year           INTEGER NOT NULL,
  quarter        INTEGER NOT NULL,
  region         TEXT    NOT NULL,
  revenue_target INTEGER NOT NULL,
  PRIMARY KEY (year, quarter, region)
);

